export const dkd_escape = dkd_value => String(dkd_value ?? '').replace(/[&<>"']/g, dkd_character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[dkd_character]);
export const dkd_money = dkd_value => Math.round(dkd_value).toLocaleString('tr-TR');
export const dkd_currency = dkd_value => `${dkd_money(Number.isFinite(Number(dkd_value)) ? Number(dkd_value) : 0)} TL`;
export const dkd_time = dkd_seconds => `${Math.floor(Math.max(0, dkd_seconds) / 60).toString().padStart(2, '0')}:${Math.floor(Math.max(0, dkd_seconds) % 60).toString().padStart(2, '0')}`;
