moon: '<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/>', shield: '<path d="m12 2 8 4v6c0 6-8 10-8 10S4 18 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>', bolt: '<path d="m14 2-9 12h7l-2 8 9-12h-7l2-8Z"/>', diamond: '<path d="m6 3-5 6 11 13L23 9l-5-6H6ZM1 9h22M6 3l6 19L18 3"/>', lock: '<rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 1 1 8 0v4M12 15v3"/>', eye: '<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>', heart: '<path d="M12 21S2 15 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 7-10 13-10 13Z"/>', medical: '<path d="M8 3h8v5h5v8h-5v5H8v-5H3V8h5V3Z"/>', chip: '<rect x="5" y="5" width="14" height="14" rx="2"/><path d="M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4"/>', truck: '<path d="M1 5h14v12H1V5Zm14 4h5l3 5v3h-8"/><circle cx="5" cy="18" r="3"/><circle cx="19" cy="18" r="3"/>', helmet: '<path d="M3 13a9 9 0 0 1 18 0v6H3v-6ZM21 11H9v4h12M6 19v3h12v-3"/>', wheel: '<circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="3"/><path d="M12 2v7M2 12h7M12 15v7M15 12h7"/>', shirt: '<path d="m7 3-6 4 3 6 3-2v11h10V11l3 2 3-6-6-4a5 5 0 0 1-10 0Z"/>', palette: '<path d="M12 2a10 10 0 1 0 0 20h2a2 2 0 0 0 0-4 2 2 0 0 1 0-4h4a4 4 0 0 0 4-4c0-5-5-8-10-8Z"/><path d="M7 8h.01M12 6h.01M17 8h.01M6 13h.01"/>', badge: '<path d="m12 2 3 3h5v5l2 3-3 3v5h-5l-3 2-3-3H3v-5l-2-3 3-3V4h5l3-2Z"/>', fingerprint: '<path d="M5 12a7 7 0 0 1 14 0v4M2 11a10 10 0 0 1 20 0M8 18v-6a4 4 0 0 1 8 0v8M12 12v10M5 16v4"/>', laptop: '<path d="M4 3h16v13H4V3ZM2 16h20v4H2v-4Z"/>', tablet: '<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M10 18h4"/>', play: '<path d="m7 3 14 9-14 9V3Z"/>', pause: '<path d="M7 4v16M17 4v16"/>', horn: '<path d="m3 9 9-4v14l-9-4V9ZM12 9h5v6h-5M20 7a7 7 0 0 1 0 10"/>', lamp: '<path d="M14 5a7 7 0 0 0 0 14V5ZM18 6h5M18 10h5M18 14h5M18 18h5"/>', fuel: '<path d="M3 22V4h11v18M5 7h7v5H5V7Zm9 7h3v5a2 2 0 0 0 4 0V9l-4-5M1 22h15"/>', clock: '<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>', volume: '<path d="M3 9h4l5-5v16l-5-5H3V9ZM16 8a6 6 0 0 1 0 8M19 4a11 11 0 0 1 0 16"/>', share: '<path d="M12 16V2m-5 5 5-5 5 5M4 12v10h16V12"/>', refresh: '<path d="M20 8a9 9 0 0 0-16 0M4 3v5h5M4 16a9 9 0 0 0 16 0m0 5v-5h-5"/>', info: '<circle cx="12" cy="12" r="10"/><path d="M12 10v7M12 6v1"/>', flag: '<path d="M5 22V3h14l-4 5 4 5H5"/>', pin: '<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>', minus: '<path d="M5 12h14"/>', plus: '<path d="M5 12h14M12 5v14"/>'
